window.MIL_EVENTS=window.MIL_EVENTS||{},window.MIL_EVENTS.general=[{t:"KP Duty",tier:"junior",i:"recycle",d:"You've been assigned to the dining facility. A mountain of greasy trays awaits and the cook is already yelling. How do you handle it?",c:[{l:"Scrub like a machine",w:{perf:5,h:-5},wt:"You finished early. The cook grunted, which counts as praise."},{l:"Hide in the dry storage",p:.4,w:{h:5},wt:"You napped behind the flour sacks. Nobody noticed.",f:{perf:-10,h:-10},ft:"The cook found you. You now own the grease trap for a week."},{l:"Eat the leftover cake",p:.6,w:{h:8,he:-2},wt:"Best sheet cake of your life. Worth it.",f:{perf:-5},ft:"Caught with frosting on your face. Extra hours added."}]},{t:"Guard Duty at 0300",tier:"junior",i:"policeman",d:"It's 0300 on gate guard. Your eyelids weigh a hundred pounds and the coffee ran out an hour ago. What do you do?",c:[{l:"Do pushups to stay awake",w:{he:2,perf:3},wt:"You stayed alert all shift. Your relief found you sweaty but awake."},{l:"Rest your eyes for a sec",p:.35,w:{h:4},wt:"You dozed for ten minutes and nobody checked. Lucky.",f:{njp:1,perf:-20,h:-15},ft:"The sergeant of the guard caught you asleep. NJP. Sleeping on post is no joke."},{l:"Chat with {buddy} on the radio",p:.6,w:{rel:5,h:3},wt:"You and {buddy} talked about cars until sunrise.",f:{perf:-8},ft:"The OD heard you tying up the net. Chewed out."}]},{t:"First Paycheck",tier:"junior",i:"star",d:'Your first real paycheck hit the account. It feels like a fortune. {buddy} says a dealership outside the gate has "military specials." What now?',c:[{l:"Buy a new muscle car",w:{h:15,money:-25e3},wt:"You signed for a 24% APR Mustang. It is gorgeous. You are broke."},{l:"Open a savings account",w:{sm:3,money:500},wt:"You squirreled it away. Future you says thanks."},{l:"Blow it all in one weekend",w:{h:10,he:-5,money:-1200},wt:"Strip club, steakhouse, tattoo. You don't remember Sunday."}]},{t:"The Car Dealer",tier:"junior",i:"policeman",d:'A salesman outside the gate says your rank qualifies you for "zero down, easy payments" on a lifted truck. The fine print is tiny. What do you do?',c:[{l:"Sign right now",w:{h:10,money:-3e4},wt:"The truck is sick. The 29% interest rate is sicker."},{l:"Read the fine print",w:{sm:4},wt:"You spotted three hidden fees and walked out. The salesman cursed in two languages."},{l:"Ask the base legal office",w:{sm:2,money:100},wt:"JAG told you it was a scam. You bought a used Corolla instead."}]},{t:"PT Test Day",tier:"junior",i:"bullseye",d:"It's PT test day. You partied last night and your stomach is doing backflips. The run starts in five minutes. What's the plan?",c:[{l:"Push through it",p:.55,w:{perf:10,he:3},wt:"You puked at the finish line but still maxed the run.",f:{perf:-10,h:-5},ft:"You failed the run by eight seconds. Remedial PT it is."},{l:"Go to sick call",p:.5,w:{h:3},wt:"The medic gave you a profile and Motrin. Test rescheduled.",f:{perf:-8},ft:"The medic saw right through you. Your squad leader is unimpressed."},{l:"Chug an energy drink",p:.45,w:{perf:8},wt:"Heart racing, you set a personal record.",f:{he:-8},ft:"Heart palpitations at mile one. You walked the rest."}]},{t:"Voluntold",tier:"junior",i:"helmet",d:'Your squad leader needs "a volunteer" to help a colonel\'s spouse move furniture on Saturday. Everyone stares at you. What do you say?',c:[{l:"Hooah, I'll do it",w:{perf:6,h:-4},wt:"You moved a piano up three flights. The spouse gave you cookies."},{l:"Claim a dentist appointment",p:.4,w:{h:4},wt:"It worked. Somebody else got the piano.",f:{perf:-8,h:-5},ft:"They checked. You now get the piano AND Sunday detail."},{l:"Volunteer {buddy} instead",w:{rel:-12,h:4},wt:"You pointed at {buddy}. {buddy} will remember this."}]},{t:"Barracks Inspection",tier:"junior",i:"policeman",d:"Surprise room inspection in ten minutes. Your room smells like dip spit and old pizza. What do you do?",c:[{l:"Speed clean everything",p:.6,w:{perf:5},wt:"You shoved everything in your truck. Room passed.",f:{perf:-8},ft:"They opened the wall locker. An avalanche of laundry."},{l:"Spray a whole can of Febreze",p:.3,w:{h:3},wt:"The inspector sniffed, coughed, and moved on.",f:{perf:-10},ft:"It smells like a pizza in a meadow. Failed."},{l:"Accept your fate",w:{perf:-6,h:-3},wt:"You failed. Weekend re-inspection for the whole floor. Everyone hates you."}]},{t:"Drill Sergeant Flashback",tier:"junior",i:"helmet",d:'You still have nightmares about your basic training instructor screaming about your "Gumby arms." Someone yells nearby and you flinch. How do you cope?',c:[{l:"Laugh it off",w:{h:4},wt:"You told the story at chow. Everyone had their own."},{l:"Lock up at attention",w:{h:-3,perf:2},wt:"You snapped to parade rest in a Walmart. A cashier was confused."}]},{t:"Energy Drink Addiction",tier:"junior",i:"fire",d:"You're up to six energy drinks a day. Your hands shake when you shave. {buddy} is worried. What do you do?",c:[{l:"Quit cold turkey",p:.5,w:{he:8,h:-4},wt:"Three days of headaches, then you felt human again.",f:{h:-8},ft:"You lasted 14 hours before raiding the shoppette."},{l:"Make it eight a day",w:{he:-10,perf:4},wt:"You are vibrating at a frequency only dogs can hear."},{l:"Switch to coffee",w:{he:3},wt:"Black coffee. Much more {branch} anyway."}]},{t:"Field Exercise Rain",tier:"junior",i:"tent",d:"Day four of a field exercise. It hasn't stopped raining, your socks are soup, and your poncho has a hole. What do you do?",c:[{l:"Change into dry socks",w:{he:4},wt:"Dry socks. The greatest luxury known to man."},{l:"Embrace the suck",w:{perf:4,he:-3,h:-3},wt:"Trench foot is starting but your team leader respects the grit."},{l:"Sneak to the heated truck",p:.45,w:{h:8},wt:"You slept in the cab like royalty.",f:{perf:-10},ft:"The platoon sergeant was already sleeping there. Bad move."}]},{t:"MRE Trading",tier:"junior",i:"tent",d:"Your squad is trading MREs. You got Veggie Omelet, the worst one. {buddy} has Chili Mac. Make a deal?",c:[{l:"Offer your jalapeno cheese",p:.6,w:{h:6,rel:3},wt:"Deal. Chili Mac is yours.",f:{h:-4},ft:"{buddy} laughed in your face. Enjoy the omelet."},{l:"Eat the omelet",w:{he:-2,h:-5},wt:"It tasted like a sponge soaked in regret."},{l:"Steal the Chili Mac",p:.4,w:{h:7,rel:-8},wt:"You swapped bags while {buddy} wasn't looking.",f:{rel:-15},ft:"{buddy} caught you. Now nobody trades with you."}]},{t:"Sleeping in Formation",tier:"junior",i:"policeman",d:"You fell asleep standing up during a long safety brief and started tipping over. The first sergeant is watching. What now?",c:[{l:"Pretend you were stretching",p:.3,w:{h:3},wt:"Somehow, he bought it.",f:{perf:-8},ft:"He did not buy it. Front leaning rest, move."},{l:"Own it",w:{perf:-3},wt:"You admitted it. Extra duty, but he respected the honesty."}]},{t:"Barracks Party",tier:"junior",i:"fire",d:"There's a party in the barracks. Someone brought a handle of vodka and a fog machine. The staff duty NCO is two floors down. Join in?",c:[{l:"Party hard",p:.5,w:{h:12,he:-4},wt:"Legendary night. You woke up in the laundry room.",f:{njp:1,perf:-15},ft:"Staff duty walked in mid-keg-stand. Everyone got NJP."},{l:"Stay in and game",w:{h:3},wt:"You played video games and heard sirens later. Good call."},{l:"Go but stay sober",w:{h:6,rel:5},wt:"You drove three drunks home. You're a hero."}]},{t:"DUI Temptation",tier:"junior",i:"policeman",d:"You've had five beers off base. It's ten minutes back to the gate. A rideshare costs $40. What do you do?",c:[{l:"Drive back",p:.4,w:{h:2},wt:"You made it back. Your hands were shaking all night.",f:{court:"DUI",demote:1,money:-3e3,h:-20},ft:"Gate guards smelled it instantly. DUI, demotion, and a career on life support."},{l:"Pay for the ride",w:{money:-40},wt:"Forty bucks well spent."},{l:"Call {buddy} for a pickup",w:{rel:4},wt:"{buddy} grumbled but came. You owe them big."}]},{t:"Tattoo Regret",tier:"junior",i:"skull",d:"You woke up in {country} with a fresh tattoo of a cartoon frog on your neck. Is that within regs?",c:[{l:"Hide it with your collar",p:.5,w:{h:2},wt:"Nobody noticed. Yet.",f:{perf:-6},ft:"The sergeant major noticed. Paperwork followed."},{l:"Pay for laser removal",w:{money:-1500,he:-2},wt:"Painful and expensive. The frog is fading."},{l:"Embrace the frog",w:{h:6,lk:-3},wt:"You named him Gerald. He's part of the team now."}]},{t:"Uniform Violation",tier:"junior",i:"policeman",d:"A senior NCO stops you on the sidewalk. Your hands are in your pockets and you're on the phone. What do you do?",c:[{l:"Apologize immediately",w:{perf:-2},wt:"A short lecture. You survived."},{l:"Argue about it",w:{perf:-10,h:-5},wt:"Twenty minutes of yelling. Your phone call ended long ago."},{l:"Pretend you didn't hear",p:.2,w:{h:3},wt:"You walked away. Somehow, it worked.",f:{perf:-12},ft:"He followed you to your unit. Your squad leader got involved."}]},{t:"Seasick",tier:"junior",i:"trident",d:"Your first day at sea and the ship is rolling hard. You're greener than your uniform. What do you do?",c:[{l:"Stare at the horizon",p:.5,w:{he:2},wt:"It helped. Your stomach found its sea legs.",f:{he:-5,h:-5},ft:"You puked over the rail. Into the wind. Onto yourself."},{l:"Eat saltines",w:{he:2},wt:"The old salts swear by it. It sort of worked."},{l:"Stay in your rack",w:{perf:-5,h:-3},wt:"Your chief dragged you out to swab the deck you puked on."}]},{t:"Port Call",tier:"junior",i:"trident",d:"The ship just docked in {country}. You have 12 hours of liberty and a buddy pair with {buddy}. What's the plan?",c:[{l:"Hit the bars",p:.5,w:{h:12,rel:5},wt:"Great night. You learned some local swear words.",f:{njp:1,h:-10},ft:"Missed liberty curfew. Captain's mast."},{l:"See the sights",w:{h:8,sm:3},wt:"Ancient ruins and street food. You sent photos home."},{l:"Stay aboard and sleep",w:{he:4},wt:"Twelve hours of glorious rack time."}]},{t:"Flight Line FOD Walk",tier:"junior",i:"jet",d:"FOD walk on the flight line at 0600. You spot a tiny bolt near a jet intake. Nobody else saw it. What do you do?",c:[{l:"Pick it up and report it",w:{perf:8},wt:"Turns out it came off a tow bar. You may have saved a $30 million engine."},{l:"Ignore it",p:.7,w:{},wt:"Nothing happened. Probably.",f:{perf:-20,h:-10},ft:"An engine ate the bolt. The investigation traced it to your lane."}]},{t:"Recruiter Lies",tier:"junior",i:"flag",d:"Your recruiter promised you'd be \"basically a pilot.\" You're cleaning latrines. What do you do?",c:[{l:"Call the recruiter",w:{h:-3},wt:"Voicemail full. Of course."},{l:"Accept the grind",w:{perf:4},wt:"Everyone starts somewhere. Your latrines sparkle."},{l:"Study for a better job",w:{sm:6},wt:"You started prepping to reclassify. Smart."}]},{t:"Hazing",tier:"junior",i:"skull",d:'Senior members of your unit say new guys have to "earn their spot" with a humiliating ritual tonight. What do you do?',c:[{l:"Go along with it",p:.6,w:{rel:6,h:-6},wt:"Degrading, but it's over. They treat you like one of them now.",f:{he:-10,h:-12},ft:"It got out of hand. You ended up at the clinic."},{l:"Report it to the IG",w:{perf:4,rel:-10},wt:"An investigation was opened. Some people won't talk to you now."},{l:"Refuse quietly",w:{h:2,rel:-4},wt:"They called you soft but left you alone."}]},{t:"Stolen Gear",tier:"junior",i:"helmet",d:"Your Kevlar is missing from your locker. Hand receipt check is tomorrow and it costs $500. What do you do?",c:[{l:"Report it missing",w:{money:-500,perf:-3},wt:"Statement of charges. Expensive lesson."},{l:'"Acquire" someone else\'s',p:.5,w:{h:3},wt:"Problem solved. Circle of life.",f:{njp:1,perf:-15},ft:"It had a name written inside. You got NJP for larceny."},{l:"Buy one at the surplus store",w:{money:-120},wt:"Close enough. Nobody checked serials."}]},{t:"Barracks Romance",tier:"junior",i:"star",d:"You've been sneaking a fellow junior enlisted from another company into your room. The rules say no overnight guests. Keep it up?",c:[{l:"Keep sneaking",p:.5,w:{h:10},wt:"Love wins. Staff duty never caught on.",f:{perf:-10,h:-6},ft:"Caught at 0500. Extra duty for both of you."},{l:"Move off base together",w:{h:8,money:-2e3},wt:"You moved out. Romantic, and expensive."},{l:"End it",w:{h:-8},wt:"You called it off. Awkward at the chow hall now."}]},{t:"Dear John Letter",tier:"junior",i:"radio",d:'Mail call. Your high school sweetheart sent a letter. It starts with "I need to tell you something..." What do you do?',c:[{l:"Read it now",w:{h:-15},wt:"They're marrying your cousin. You stared at the wall for hours."},{l:"Burn it unread",w:{h:-5},wt:"Ignorance is bliss. Mostly."},{l:"Read it with {buddy}",w:{h:-8,rel:8},wt:"It was bad news. {buddy} bought you a pizza and roasted your ex."}]},{t:"Rifle Range",tier:"junior",i:"bullseye",d:"Qualification day at the range. You're borderline and the wind is gusting. What's your approach?",c:[{l:"Breathe and focus",p:.65,w:{perf:8,h:4},wt:"You shot expert. Badge on the chest.",f:{perf:-5},ft:"You missed qualifying by one. Back to the range."},{l:"Ask a coach for tips",w:{sm:3,perf:4},wt:"Adjusted your zero. Qualified sharpshooter."},{l:"Spray and pray",p:.2,w:{perf:3},wt:"Somehow you qualified marksman.",f:{perf:-8},ft:'The range officer just said "No."'}]},{t:"Shoppette Run",tier:"junior",i:"helmet",d:'Your team leader hands you $20 and says, "Get me a pack of smokes, a dip, and a Rip It. Keep the change." There\'s no change. Go?',c:[{l:"Cover the difference",w:{money:-6,rel:3},wt:"You paid the rest. Team leader owes you one."},{l:"Point out the math",w:{perf:-2,sm:1},wt:"He gave you another five and a dirty look."}]},{t:"Payday Loan",tier:"junior",i:"recycle",d:'You\'re short on rent for your off-base apartment. A payday lender near the gate offers instant cash at "low" rates. What do you do?',c:[{l:"Take the loan",w:{money:500,h:2},wt:"You paid rent. The 300% APR will haunt you."},{l:"Go to the relief society",w:{money:400,sm:2},wt:"Interest-free loan from military relief. Lifesaver."},{l:"Sell your PlayStation",w:{money:300,h:-5},wt:"Rent paid. Boredom achieved."}]},{t:"Stray Dog on Base",tier:"junior",i:"helmet",d:"A scrawny stray dog keeps following your squad around base. Pets are banned in the barracks. What do you do?",c:[{l:"Adopt it secretly",p:.4,w:{h:15},wt:"You named it Private Biscuit. Morale is through the roof.",f:{perf:-8,h:-8},ft:"Animal control took Biscuit. Paperwork for you."},{l:"Take it to a shelter",w:{h:5},wt:"Biscuit found a family. You visit sometimes."},{l:"Feed it MREs",w:{h:6},wt:"The dog likes the jalapeno cheese more than you do."}]},{t:"Guard Mount Lie",tier:"junior",i:"policeman",d:"{buddy} skipped their guard shift and asks you to tell the sergeant they were there. What do you say?",c:[{l:"Cover for {buddy}",p:.5,w:{rel:10},wt:"The sergeant believed you. {buddy} owes you forever.",f:{njp:1,rel:5,perf:-12},ft:"Caught lying on an official statement. You both got NJP."},{l:"Tell the truth",w:{rel:-15,perf:4},wt:"You told the truth. {buddy} stopped talking to you."}]},{t:"Social Media Leak",tier:"junior",i:"laptop",d:'You took a cool selfie in front of a classified screen and almost hit "post." What do you do?',c:[{l:"Post it anyway",p:.2,w:{h:5},wt:"It got 40 likes and nobody noticed. Dumb luck.",f:{court:"mishandling classified information",demote:1,h:-20},ft:"Security found it within an hour. Court-martial for mishandling classified info."},{l:"Delete it",w:{sm:2},wt:"You deleted it and sweated for a week."},{l:"Crop it and post",p:.6,w:{h:4},wt:"Cropped clean. Good selfie.",f:{njp:1,perf:-10},ft:"A reflection in your sunglasses showed the screen. NJP."}]},{t:"Gas Chamber",tier:"junior",i:"skull",d:"CBRN training. You're in the gas chamber and the instructor tells you to take off your mask and recite your social. What do you do?",c:[{l:"Do it calmly",w:{perf:4,he:-3},wt:"Snot everywhere, but you stayed calm. Respect earned."},{l:"Panic and run",w:{perf:-5,he:-4,h:-4},wt:"You bolted. The instructors made you go back in."}]},{t:"Ruck Blisters",tier:"junior",i:"compass",d:"Twelve miles into a ruck march, your heel feels like it's on fire. You're near the back. What do you do?",c:[{l:"Keep marching",p:.65,w:{perf:8,he:-4},wt:"You finished. Your sock is stuck to your foot with blood.",f:{he:-8,perf:-3},ft:"Your foot gave out. You rode in the sag wagon."},{l:"Stop and moleskin it",w:{he:2,perf:2},wt:"Thirty seconds of moleskin. You finished strong."},{l:"Fall out",w:{perf:-8,h:-4},wt:"The sag wagon of shame."}]},{t:"Spice Offer",tier:"junior",i:"skull",d:'A guy in the barracks offers you synthetic weed and swears "it doesn\'t show up on a piss test." What do you do?',c:[{l:"Try it",p:.3,w:{h:5},wt:"You felt weird for a day. Never again.",f:{discharge:"general",h:-20},ft:"Random urinalysis caught it. You're being separated."},{l:"Refuse",w:{sm:2},wt:"Two weeks later he got caught. Good call."},{l:"Report him",w:{perf:5,rel:-5},wt:"CID raided his room. Some people call you a snitch."}]},{t:"Wrong Salute",tier:"junior",i:"eagle",d:"You just saluted a warrant officer's cousin who's wearing civilian clothes. Then you failed to salute an actual officer. What now?",c:[{l:"Run after the officer",w:{perf:2},wt:"You caught up and saluted. The officer laughed."},{l:"Pretend nothing happened",p:.5,w:{},wt:"Nobody cared.",f:{perf:-5},ft:"The officer chewed you out in front of the PX."}]},{t:"Lost Weapon",tier:"junior",i:"gun",d:"You set your rifle down for one second in the field and now it's gone. The whole battalion is about to halt. What do you do?",c:[{l:"Report it immediately",w:{perf:-10,h:-8},wt:"Your sergeant found it 30 feet away. You'll carry a broomstick for a month."},{l:"Search frantically alone",p:.4,w:{h:5},wt:"Found it under a bush. Nobody knows.",f:{njp:1,perf:-20},ft:"You waited too long. The whole battalion searched. NJP."}]},{t:"Sick Call Ranger",tier:"junior",i:"stethoscope",d:"Your knee hurts a little. {buddy} says go to sick call to skip the ruck march. Do it?",c:[{l:"Go to sick call",p:.5,w:{h:5},wt:"You got a light-duty profile. Easy week.",f:{perf:-6},ft:'Medic said walk it off. Now they call you "Sick Call Ranger."'},{l:"Ruck anyway",w:{perf:5,he:-3},wt:"You finished. Knee is angry, but you earned respect."}]},{t:"Coast Guard Rescue Swim",tier:"junior",i:"helicopter",d:"A fishing boat capsized in rough seas. Your crew is first on scene and a man is drowning 30 meters out. What do you do?",c:[{l:"Throw a ring buoy",p:.7,w:{perf:10,h:10},wt:"Perfect throw. You hauled him in.",f:{h:-10},ft:"The wind carried it off. A helicopter got him, barely."},{l:"Jump in after him",p:.6,w:{perf:15,h:12,medal:"Army Commendation Medal"},wt:"You pulled him out against the swell. Commendation incoming.",f:{he:-20,die:.05,cause:"drowned during a rescue"},ft:"The surf hammered you. You barely made it back."}]},{t:"Tough Barracks Room",tier:"junior",i:"tent",d:"Your new roommate never showers, plays drums at 2 AM, and eats your food. What do you do?",c:[{l:"Talk to him",p:.5,w:{h:5},wt:"He agreed to shower. Small victories.",f:{h:-5},ft:"He shrugged and started drumming again."},{l:"Tell your squad leader",w:{h:4},wt:"He got moved. Peace at last."},{l:"Blanket party",p:.4,w:{h:4},wt:"He got the message. He showers now.",f:{njp:1,perf:-15},ft:"He reported it. You got NJP for assault."}]},{t:"Military Ball",tier:"junior",i:"medal",d:"The unit ball is this weekend. You have no date and the grog bowl looks suspicious. What do you do?",c:[{l:"Go and drink the grog",w:{h:8,he:-4},wt:"It contained Tabasco, rum, and a boot. You loved it."},{l:'Bring {buddy} as a "date"',w:{h:8,rel:8},wt:"You two danced to Cotton Eye Joe. Legendary."},{l:"Skip it",w:{perf:-2},wt:"Your first sergeant noticed. Mandatory fun is mandatory."}]},{t:"Re-Up Bonus Pitch",tier:"junior",i:"flag",d:"The career counselor waves a $20,000 re-enlistment bonus at you. Your contract ends in eight months. Sign?",c:[{l:"Sign it",w:{money:2e4,h:5},wt:"You re-upped. Time to buy a boat you don't need."},{l:"Think it over",w:{sm:2},wt:"You're weighing the GI Bill against the cash."},{l:"Laugh and walk away",w:{h:3},wt:"Counting days. Civilian life is calling."}]},{t:"Overslept",tier:"junior",i:"helmet",d:"You woke up at 0640. Formation was at 0630. Your phone shows 17 missed calls. What do you do?",c:[{l:"Sprint to formation",w:{perf:-5},wt:"You showed up with toothpaste on your face. Counseling statement."},{l:"Claim food poisoning",p:.4,w:{h:2},wt:"They bought it and sent you to sick call.",f:{perf:-10},ft:"Your squad leader saw your bar tab from last night on Instagram."}]},{t:"Convoy Driver",tier:"junior",i:"map",d:"You're driving a truck in a convoy at night on blackout drive. The NVGs are fogging up and the road is narrow. What's your move?",c:[{l:"Slow down",p:.8,w:{perf:4},wt:"You kept your interval. The convoy arrived safe.",f:{perf:-5},ft:"You fell behind and got lost for 20 minutes."},{l:"Keep pace no matter what",p:.5,w:{perf:6},wt:"Smooth driving. Your truck commander was impressed.",f:{he:-15,perf:-10},ft:"You rolled into a ditch. Truck on its side, bruised ribs."}]},{t:"Barracks Fire Alarm",tier:"junior",i:"fire",d:"Someone burned popcorn and the barracks fire alarm is going off at 0200. Everyone has to stand outside in the cold. You know who did it. Say?",c:[{l:"Rat them out",w:{rel:-5,perf:2},wt:"The microwave was confiscated from the whole floor."},{l:"Stay quiet",w:{h:-3},wt:"You froze for an hour. Solidarity."}]},{t:"Base Gym Rat",tier:"junior",i:"bullseye",d:"The gym on base is free and open 24/7. {buddy} wants to start a bulking program together. In?",c:[{l:"Lift every day",w:{he:8,lk:5,rel:5},wt:"Six weeks later, your sleeves are tight."},{l:"Try supplements",p:.6,w:{he:5,lk:6},wt:"Gains are real.",f:{he:-6},ft:"Sketchy pre-workout gave you heart palpitations."},{l:"Nah, video games",w:{h:4,he:-2},wt:"You maxed a different kind of level."}]},{t:"Barracks Thief",tier:"junior",i:"policeman",d:"Money keeps disappearing from rooms. You catch a guy from your squad walking out of a neighbor's room with a wallet. What do you do?",c:[{l:"Confront him",p:.5,w:{perf:4},wt:"He returned it and confessed to the chain of command.",f:{he:-5},ft:"He swung at you and ran."},{l:"Report to the NCO",w:{perf:5},wt:"He was caught and kicked out."},{l:"Look away",w:{h:-4},wt:"Your wallet went missing next."}]},{t:"Chewed Out",tier:"junior",i:"helmet",d:"{rank} {name}, your platoon sergeant is screaming at you inches from your face because your boots aren't shined. How do you react?",c:[{l:"Stare straight ahead",w:{perf:2},wt:"You let it wash over you. It ended eventually."},{l:"Smirk",w:{perf:-10,h:-5},wt:"Mistake. Push-ups until your arms gave up."},{l:'Say "Roger, Sergeant"',w:{perf:3},wt:"Textbook response. He walked off satisfied."}]},{t:"Troubled Private",tier:"nco",i:"helmet",d:"One of your junior soldiers has been late three times this week and smells like booze. He looks exhausted. How do you handle it?",c:[{l:"Counsel him privately",w:{perf:6},wt:"He admitted his marriage is falling apart. You got him to chaplain support."},{l:"Smoke him in front of everyone",w:{perf:-3,h:2},wt:"He's sore and humiliated. The real problem remains."},{l:"Send him to the ASAP program",w:{perf:4},wt:"Substance abuse counseling. He thanked you a year later."}]},{t:"NCO Evaluation",tier:"nco",i:"laptop",d:'Your evaluation is due and your rater wrote "solid performer." In promotion-speak, that\'s a death sentence. What do you do?',c:[{l:"Push back politely",p:.6,w:{perf:10},wt:'You got "Most Qualified" with strong bullets.',f:{perf:-4},ft:"Your rater got defensive. Eval unchanged."},{l:"Accept it",w:{h:-6},wt:"Promotion just got a lot harder."},{l:"Write your own bullets",w:{perf:7,sm:2},wt:"Your rater copied them word for word."}]},{t:"Promotion Board",tier:"nco",i:"medal",d:"You're in front of the promotion board. The sergeant major asks you to recite the NCO Creed. Your mind goes blank. What do you do?",c:[{l:"Take a breath and go",p:.6,w:{promote:1,h:10},wt:"You nailed it. Selected for promotion.",f:{perf:-5,h:-5},ft:"You stumbled on the second paragraph. Not selected this time."},{l:"Admit you blanked",p:.4,w:{promote:1,perf:3},wt:"They appreciated the honesty and your other answers carried you.",f:{h:-5},ft:"Not this time."}]},{t:"Ruck March Leadership",tier:"nco",i:"compass",d:"You're leading a 12-mile ruck. One of your soldiers is falling way behind and crying. How do you handle it?",c:[{l:"Carry part of his load",w:{perf:8,he:-4},wt:"You took his radio. The whole squad finished together."},{l:"Yell motivation at him",p:.5,w:{perf:5},wt:"He found a second wind.",f:{perf:-4},ft:"He collapsed. Heat casualty. Investigation pending."},{l:"Drop him to the sag wagon",w:{perf:-2},wt:"He's safe, but squad pride took a hit."}]},{t:"Soldier Arrested",tier:"nco",i:"policeman",d:"It's 0300. Off-post police call: one of your soldiers was arrested for fighting outside a club. What do you do?",c:[{l:"Go pick him up",w:{perf:5,h:-4},wt:"You bailed him out and got the story. He was defending a friend."},{l:"Let him sit till morning",w:{perf:2},wt:"A night in jail taught him something."},{l:"Ignore your phone",w:{perf:-8},wt:"The first sergeant had to go. He was not pleased with you."}]},{t:"Suicide Warning Signs",tier:"nco",i:"stethoscope",d:'A young soldier has been giving away his gear and says "it won\'t matter soon." What do you do?',c:[{l:"Ask him directly",w:{perf:10,h:5},wt:"You asked. He admitted it. You walked him to behavioral health. He's alive."},{l:"Tell the chain of command",w:{perf:6},wt:"He was escorted to help. You check on him daily."},{l:"Assume he's joking",p:.5,w:{},wt:"He was okay. You still feel uneasy.",f:{h:-25},ft:"He took his own life two days later. You will carry this forever."}]},{t:"Barracks Raid",tier:"nco",i:"policeman",d:"You're staff duty NCO and hear music and laughter coming from a room after quiet hours. Smells like weed. What do you do?",c:[{l:"Knock and enter",w:{perf:6},wt:"Three soldiers with a vape full of THC. You did your job."},{l:"Turn down the music and leave",w:{perf:-3},wt:"You avoided the drama. For now."},{l:"Call the MPs",w:{perf:4},wt:"They hauled them off. The commander is pleased."}]},{t:"Mentoring a Rookie",tier:"nco",i:"star",d:"A new private with a lot of potential asks you how to make sergeant fast. What advice do you give?",c:[{l:"Study, PT, volunteer",w:{perf:4,h:4},wt:"Two years later, he pinned sergeant and thanked you."},{l:"Tell him to kiss up",w:{perf:-2},wt:"He became a brown-noser. Yikes."},{l:'"Don\'t get caught."',w:{h:3},wt:"He laughed. Classic NCO wisdom."}]},{t:"Sergeant's Time Training",tier:"nco",i:"map",d:"You have to teach a class to your squad on land navigation. Half of them are falling asleep. What do you do?",c:[{l:"Take them outside",w:{perf:6},wt:"Hands-on with a real map. Everyone learned something."},{l:"Read the PowerPoint",w:{perf:-3},wt:"Even you fell asleep."},{l:"Make it a competition",w:{perf:8,rel:4},wt:"Winners got a day off. Suddenly everyone loves land nav."}]},{t:"Pencil-Whipped Inventory",tier:"nco",i:"laptop",d:'Inventory is due. You\'re missing two night vision devices worth $8,000 each. Someone suggests "adjusting" the paperwork. What do you do?',c:[{l:"Report it honestly",w:{perf:-5,sm:2},wt:"Investigation found them in another unit's connex. Close call."},{l:"Fudge the numbers",p:.4,w:{h:2},wt:"Nobody checked. You sleep badly.",f:{court:"falsifying official records",demote:1,h:-15},ft:"An audit caught it. Court-martial for false official records."}]},{t:"Soldier Pregnant",tier:"nco",i:"stethoscope",d:"One of your soldiers tells you she's pregnant and scared to tell the chain of command. What do you do?",c:[{l:"Support her",w:{perf:5,h:4},wt:"You helped her get the right profile and resources."},{l:"Gossip about it",w:{perf:-10},wt:"Word got around. She filed an EO complaint."}]},{t:"Bad Lieutenant",tier:"nco",i:"compass",d:"Your new lieutenant insists the platoon walk the wrong direction on a land nav exercise. He's confident. You know he's wrong. What do you do?",c:[{l:"Correct him privately",w:{perf:6},wt:"He listened. Crisis averted. He trusts you now."},{l:"Let him fail",w:{h:3,perf:-2},wt:"Three hours lost. He learned. So did the company commander."},{l:"Correct him in public",w:{perf:-3,rel:3},wt:"The platoon loved it. He didn't."}]},{t:"NCO Academy",tier:"nco",i:"medal",d:"You're at the NCO academy. You could aim for the Commandant's List but it means no sleep. Worth it?",c:[{l:"Go all out",p:.5,w:{perf:12,sm:4},wt:"Commandant's List. Your career just accelerated.",f:{he:-4},ft:"You burned out and finished middle of the pack."},{l:"Just pass",w:{h:4},wt:"Graduated. You slept eight hours a night."}]},{t:"Domestic Call",tier:"nco",i:"policeman",d:'One of your married soldiers shows up with scratches on his face. He says "it\'s nothing." What do you do?',c:[{l:"Check in with him",w:{perf:5},wt:"He opened up. You connected him and his spouse with the family advocacy program."},{l:"Mind your business",w:{h:-3},wt:"Things got worse. MPs got involved two weeks later."}]},{t:"Pay Problem",tier:"nco",i:"laptop",d:'Finance shorted one of your soldiers $1,500 and he can\'t pay rent. Finance says "two to three pay periods." What do you do?',c:[{l:"Storm the finance office",p:.6,w:{perf:6},wt:"You camped there until it got fixed. Hero to your soldier.",f:{perf:-3},ft:"The finance clerk took your yelling personally. Even slower now."},{l:"Loan him money",w:{money:-1500,rel:10},wt:"He paid you back. You built serious loyalty."},{l:"Tell him to suck it up",w:{perf:-5},wt:"He got evicted. Morale in the squad dropped."}]},{t:"Fraternization",tier:"nco",i:"star",d:"You've developed feelings for a private in your own platoon. They seem to feel the same. What do you do?",c:[{l:"Start dating secretly",p:.3,w:{h:12},wt:"Nobody found out. You're walking a razor's edge.",f:{njp:1,demote:1,h:-15},ft:"Someone saw you holding hands. Fraternization. Busted down a rank."},{l:"Request a transfer",w:{h:5},wt:"You moved units. Now it's legal. Mostly."},{l:"Shut it down",w:{h:-6,perf:3},wt:"The right call. It still stings."}]},{t:"Range Safety",tier:"nco",i:"gun",d:"You're range safety. A private turns around with a loaded weapon pointing down the firing line. What do you do?",c:[{l:'Yell "CEASE FIRE!"',w:{perf:8},wt:"Everyone froze. You redirected the barrel. Nobody died today."},{l:"Tackle him",p:.7,w:{perf:10},wt:"You took him down safely. Weapon pointed downrange.",f:{wound:1,he:-15},ft:"A round went off into the dirt and grazed your leg."}]},{t:"Prepping a Board",tier:"nco",i:"star",d:"Your best specialist has the soldier of the quarter board tomorrow. He's nervous. Do you help?",c:[{l:"Drill him all night",w:{perf:8,he:-2},wt:"He won. Your squad has bragging rights."},{l:"Tell him to wing it",p:.3,w:{perf:3},wt:"He won anyway. Natural talent.",f:{perf:-2},ft:"He bombed. The other squad leader smirked."}]},{t:"Hungover Squad",tier:"nco",i:"helmet",d:"Monday morning. Your whole squad is visibly hungover after a three-day weekend. PT is about to start. What do you do?",c:[{l:"Smoke check them",w:{perf:4,rel:-4},wt:"Ninety minutes of burpees. Lesson learned."},{l:"Easy run, hydration",w:{rel:6},wt:"They appreciated the mercy. Loyalty earned."}]},{t:"The Chief's Coffee",tier:"nco",i:"trident",d:"Aboard ship, you discover a junior sailor has been brewing the chief's mess coffee with week-old grounds. The chiefs are furious. Cover for him?",c:[{l:"Take the blame",w:{perf:-3,rel:8},wt:"The chiefs hazed you a bit. Your sailor will die for you now."},{l:"Throw him under the bus",w:{perf:2},wt:"He scrubbed the coffee urn with a toothbrush."}]},{t:"Uniform Inspection",tier:"nco",i:"medal",d:"You're inspecting dress uniforms. One soldier has his ribbons upside down and a missing badge. Inspection is in an hour. What do you do?",c:[{l:"Fix it with him",w:{perf:5},wt:"Ten minutes with a ruler. Passed."},{l:"Let him fail",w:{perf:-3},wt:"He failed. Squad looks bad."}]},{t:"Quarters Housing Mold",tier:"nco",i:"recycle",d:"Your family's base housing has black mold in the bathroom. Your kid has been coughing. Privatized housing says it's \"a cosmetic issue.\" What do you do?",c:[{l:"Escalate to the garrison",p:.6,w:{h:6},wt:"They moved you to a new unit within a week.",f:{h:-8},ft:"They painted over it. Your kid still coughs."},{l:"Move off post",w:{money:-3e3,h:4},wt:"Expensive, but you breathe easier."},{l:"Go to the local news",p:.5,w:{h:8},wt:"The story aired. Repairs started the next day.",f:{perf:-8},ft:"The garrison commander was not happy with you."}]},{t:"Ruck Inspection",tier:"nco",i:"tent",d:"Before a field exercise, you find a private's ruck is stuffed with pillows to look full. What do you do?",c:[{l:"Make him repack it",w:{perf:3},wt:"Proper load. He grumbled."},{l:"Make him carry a sandbag too",w:{perf:4,rel:-3},wt:"He won't try that again."},{l:"Laugh and let it go",w:{rel:5,perf:-4},wt:"Your squad thinks you're cool. The first sergeant doesn't."}]},{t:"Sexual Harassment Report",tier:"nco",i:"policeman",d:"A soldier tells you another NCO has been sending her inappropriate messages. The NCO is your friend. What do you do?",c:[{l:"Report it",w:{perf:6,rel:-5},wt:"An investigation opened. Doing the right thing cost you a friendship."},{l:"Talk to your friend first",w:{perf:-4},wt:"He denied it and deleted everything."}]},{t:"Overweight Soldier",tier:"nco",i:"bullseye",d:"One of your soldiers failed tape test again. One more and he's chaptered out. He really wants to stay. What do you do?",c:[{l:"Train with him daily",w:{he:5,perf:6},wt:"He dropped 20 pounds and passed."},{l:"Process the separation",w:{perf:2,h:-3},wt:"Rules are rules. He went home."}]},{t:"Sergeant Major's Eye",tier:"nco",i:"eagle",d:"The command sergeant major spotted your soldiers walking on the grass. He wants to see you in his office. What do you say?",c:[{l:"Take responsibility",w:{perf:3},wt:"He respected that. Mostly."},{l:"Blame the soldiers",w:{perf:-5},wt:'"Who\'s their leader, Sergeant?" Ouch.'}]},{t:"Pick Up Rank",tier:"nco",i:"medal",d:"You made the cut-off score for promotion. The pinning ceremony is Friday and your family wants to come. Hold a party?",c:[{l:"Host a barbecue",w:{promote:1,h:10,money:-400},wt:"Promotion pinned. Brisket smoked. Life is good."},{l:"Keep it low-key",w:{promote:1,h:6},wt:"Pinned on the motor pool floor. Humble."}]},{t:"Flight Line Accident",tier:"nco",i:"jet",d:"Your crew is rushing an aircraft for launch. A junior airman skipped a torque check to save time. Launch is in 10 minutes. What do you do?",c:[{l:"Delay the launch",w:{perf:6},wt:"You found a loose panel. Maintenance officer quietly thanked you."},{l:"Let it go",p:.6,w:{perf:2},wt:"It flew fine.",f:{perf:-20,h:-15},ft:"A panel tore off in flight. Safety investigation names you."}]},{t:"Deployment Notice",tier:"nco",i:"flag",d:"Your unit got orders. You deploy to {country} in 60 days. Your spouse just found out. How do you break it?",c:[{l:"Plan a nice dinner",w:{h:4},wt:"Tears, but you made a plan together."},{l:"Blurt it out",w:{h:-6},wt:"Not your finest moment. It led to a fight."},{l:"Volunteer to stay back",p:.3,w:{h:8},wt:"You got rear detachment. Your spouse is relieved.",f:{perf:-6},ft:"Denied. And your first sergeant thinks you're soft."}]},{t:"Squad PT Champion",tier:"nco",i:"bullseye",d:"The battalion is holding a PT competition. Your squad can win a four-day pass. What's your strategy?",c:[{l:"Train them hard",p:.6,w:{perf:10,h:8},wt:"Your squad won. Four-day weekend!",f:{h:-4},ft:"Second place. No pass."},{l:"Recruit the fittest guy",p:.5,w:{perf:6},wt:"He carried you to victory.",f:{perf:-3},ft:"He pulled a hamstring on day one."}]},{t:"Dead Animal in HVAC",tier:"nco",i:"skull",d:"Your shop smells like death. A raccoon died in the ventilation system. Maintenance says six weeks. What do you do?",c:[{l:"Crawl in yourself",w:{perf:5,he:-4},wt:"You removed it. You will never smell normal again."},{l:"Order the junior troops to do it",w:{perf:3,rel:-4},wt:"Done. A private threw up twice."},{l:"Work outside",w:{h:3},wt:"Office under a tree. Peaceful."}]},{t:"Gold Star Family",tier:"nco",i:"flag",d:"You're detailed as a casualty notification NCO. You have to knock on a family's door to tell them their son died. How do you prepare?",c:[{l:"Rehearse with the chaplain",w:{h:-10,perf:4},wt:"You did it with dignity. You cried in the car afterward."},{l:"Just go",w:{h:-14},wt:"The mother screamed. You will hear it forever."}]},{t:"Old School vs New School",tier:"nco",i:"helmet",d:"Your senior NCO wants to smoke the platoon for a minor mistake. You think it's pointless. Speak up?",c:[{l:"Push back respectfully",p:.5,w:{perf:5,rel:4},wt:"He agreed to a retraining instead.",f:{perf:-4},ft:"He smoked you too."},{l:"Go along with it",w:{rel:-3},wt:"The platoon suffered. Nobody learned anything."}]},{t:"Spouse Club Drama",tier:"nco",i:"star",d:"Your spouse got into a feud with the first sergeant's spouse at the family readiness group. Now it's affecting work. What do you do?",c:[{l:"Stay out of it",w:{h:-3},wt:"It blew over in three months. Very long months."},{l:"Ask your spouse to apologize",p:.5,w:{perf:4},wt:"Peace restored.",f:{h:-10},ft:"You slept on the couch for a week."}]},{t:"Drill Sergeant Duty",tier:"nco",i:"helmet",d:"You've been selected for drill sergeant or recruiter duty. Both are brutal but career-enhancing. Which?",c:[{l:"Drill sergeant",w:{perf:10,h:-6,he:4},wt:"You got the hat. You now yell for a living."},{l:"Recruiter",w:{perf:8,h:-8},wt:"Strip mall office, quotas, and lies. Welcome to recruiting."}]},{t:"Sailor Overboard Drill",tier:"nco",i:"trident",d:"A real person-overboard alarm sounds at night. You're the senior petty officer on deck. What do you do?",c:[{l:"Run the drill by the book",w:{perf:8},wt:"Life ring thrown, spotters out, sailor recovered in nine minutes."},{l:"Dive in after them",p:.5,w:{perf:10,medal:"Navy & Marine Achievement Medal"},wt:"You got them. Reckless, but it worked.",f:{he:-20,die:.08,cause:"drowned at sea"},ft:"The swells nearly took you too."}]},{t:"Reenlistment Talk",tier:"nco",i:"flag",d:"Your best soldier wants to get out. The command wants retention numbers. He asks for honest advice. What do you say?",c:[{l:"Tell him the truth",w:{h:4},wt:"He got out, went to college, and still texts you."},{l:"Push the reenlistment",w:{perf:5},wt:"He re-upped. You hope he doesn't regret it."}]},{t:"Lost Lieutenant",tier:"officer",i:"compass",d:"Your platoon has been walking for two hours. You're pretty sure the objective is north. Your platoon sergeant is giving you a look. What do you do?",c:[{l:"Ask the platoon sergeant",w:{perf:3,sm:2},wt:"He pointed the right way. Ego bruised, mission saved."},{l:"Trust your map skills",p:.4,w:{perf:6},wt:"You were right! Shock in the platoon.",f:{perf:-8,h:-5},ft:"You led them to a cow pasture. The story will follow you forever."},{l:"Blame the GPS",w:{perf:-3},wt:"Nobody believes you."}]},{t:"Death by PowerPoint",tier:"officer",i:"laptop",d:"The battalion commander wants a 50-slide brief on vehicle maintenance by 0700. It's 2200. What do you do?",c:[{l:"Grind all night",w:{perf:8,he:-4},wt:'Every slide perfect. The commander said "good." Just "good."'},{l:"Recycle an old brief",p:.5,w:{perf:4,h:3},wt:"Nobody noticed the dates. Asleep by 2300.",f:{perf:-10},ft:"Slide 12 still had the old unit's name on it."},{l:"Make it 10 slides",p:.5,w:{perf:6},wt:"He loved the brevity.",f:{perf:-6},ft:'"Where\'s the rest?"'}]},{t:"OER Season",tier:"officer",i:"laptop",d:"Officer evaluation reports are due. Your rater is a micromanager who hasn't seen half your work. What do you do?",c:[{l:"Submit a strong support form",w:{perf:6,sm:2},wt:"He used it almost verbatim. Top block."},{l:"Trust the process",p:.4,w:{perf:4},wt:"Decent rating.",f:{perf:-8},ft:'"Center of mass." Career speed bump.'}]},{t:"Platoon Leader Debut",tier:"officer",i:"helmet",d:"You're a brand new platoon leader. Thirty soldiers are sizing you up. Your first speech?",c:[{l:"Humble and short",w:{perf:6},wt:'"I\'m here to learn and lead." They respected it.'},{l:"Long, motivational",w:{perf:-3},wt:"Someone yawned audibly."},{l:"Quote a movie",w:{perf:-2,h:3},wt:"They laughed. At you, not with you."}]},{t:"Company Command",tier:"officer",i:"flag",d:"You took command of a company. Morale is low, and there's a problem first sergeant. Where do you start?",c:[{l:"Work with the first sergeant",p:.6,w:{perf:10},wt:"You found common ground. The company is turning around.",f:{perf:-5},ft:"He undermines you at every turn."},{l:"Replace him",w:{perf:5,h:-4},wt:"Battalion approved. Painful, but necessary."},{l:"Focus on the soldiers",w:{perf:6,h:4},wt:"Cookouts, recognition, fair duty roster. Morale climbing."}]},{t:"Command Inspection",tier:"officer",i:"policeman",d:"The inspector general team arrives Monday to inspect your unit. Your arms room records are a mess. What do you do?",c:[{l:"All-weekend fix party",w:{perf:8,h:-6},wt:"Passed with zero findings. Nobody saw their family for 48 hours."},{l:"Hope for the best",p:.3,w:{perf:2},wt:"They didn't look at the arms room. Miracle.",f:{perf:-15},ft:"Massive findings. The colonel wants a word."}]},{t:"Supply Loss",tier:"officer",i:"laptop",d:"Your company lost $40,000 of gear during a field exercise. As commander, you're financially liable if negligence is found. What do you do?",c:[{l:"Launch an honest investigation",w:{perf:4},wt:"It was a theft, not negligence. You're cleared."},{l:"Shift blame to a sergeant",p:.5,w:{h:2},wt:"He paid. You feel awful.",f:{perf:-15},ft:"The investigating officer saw through it. Relieved of command."}]},{t:"Saluting Gauntlet",tier:"officer",i:"eagle",d:"You're a new second lieutenant walking past 200 soldiers outside the PX. Your arm is getting tired from saluting. What do you do?",c:[{l:"Salute every single one",w:{perf:2,he:1},wt:"Your shoulder hurts. Discipline maintained."},{l:"Take a different route",w:{h:3},wt:"You walked behind the dumpsters. Smart."}]},{t:"The Butter Bar",tier:"officer",i:"star",d:'A crusty sergeant first class "accidentally" calls you "Ensign" and "Kid" in front of the platoon. How do you respond?',c:[{l:"Laugh it off",w:{rel:4},wt:"He grinned. You earned a sliver of respect."},{l:"Correct him sharply",w:{perf:2,rel:-6},wt:"You won the battle. Not the war."}]},{t:"Field Grade Briefing",tier:"officer",i:"laptop",d:"You're briefing the brigade commander. Halfway in, the projector dies. All eyes are on you. What do you do?",c:[{l:"Brief from memory",p:.6,w:{perf:10},wt:'Calm and clear. "That\'s how you brief," the colonel said.',f:{perf:-6},ft:"You blanked on the key numbers."},{l:"Ask for a 5-minute break",w:{perf:-2},wt:"IT fixed it. Momentum lost."}]},{t:"Fraternizing Officer",tier:"officer",i:"star",d:"You're attracted to a sergeant in your chain of command. They flirt back at the unit ball. What do you do?",c:[{l:"Shut it down",w:{perf:3,h:-3},wt:"Career intact. Heart a bit sad."},{l:"Pursue it",p:.25,w:{h:10},wt:"Nobody found out. For now.",f:{njp:1,perf:-25,discharge:"general"},ft:"It came out in an investigation. You resigned your commission."}]},{t:"Training Schedule",tier:"officer",i:"map",d:"Battalion piled four new taskings onto your training calendar this week. Your soldiers are exhausted. What do you do?",c:[{l:"Push back up the chain",p:.5,w:{perf:6,rel:6},wt:"Two taskings got moved. The troops noticed.",f:{perf:-4},ft:'"Make it happen, Captain."'},{l:"Do it all",w:{perf:4,h:-6},wt:"Done. Everyone is fried."}]},{t:"The Missing Rifle",tier:"officer",i:"gun",d:"After a field exercise, your company is short one rifle. Nobody leaves until it's found. It's 2100 Friday. What do you do?",c:[{l:"Lead the search yourself",p:.7,w:{perf:5},wt:"Found it in a truck bed at 0100.",f:{perf:-12},ft:"Search went into Sunday. Brigade got involved."},{l:"Delegate and go home",w:{perf:-8},wt:"Your troops won't forget that you left."}]},{t:"Sexual Assault Case",tier:"officer",i:"policeman",d:"A soldier reports being assaulted by a popular team leader. The team leader's squad is pressuring the victim. What do you do?",c:[{l:"Protect the victim",w:{perf:8},wt:"You separated them and stopped the retaliation. The case moved forward."},{l:"Wait for the investigation",w:{perf:-6},wt:"The victim felt abandoned and requested a transfer."}]},{t:"Ship Division Officer",tier:"officer",i:"trident",d:'You\'re a new division officer aboard ship. Your chief says, "Sir, let me handle the sailors. You handle the paperwork." How do you respond?',c:[{l:"Agree and learn",w:{perf:6,sm:3},wt:"Best advice you ever got. Your division runs smoothly."},{l:"Assert yourself",w:{perf:-3},wt:"The chief smiled. You'll learn."}]},{t:"Pilot Training Washout",tier:"officer",i:"jet",d:"Your flight instructor says you're on the edge of washing out of flight school. One more checkride. How do you prepare?",c:[{l:"Chair-fly for hours",p:.65,w:{perf:10,h:10},wt:"You passed. Wings are within reach.",f:{h:-15,perf:-8},ft:"Washed out. You'll be a logistics officer now."},{l:"Get some sleep",p:.5,w:{perf:8},wt:"Rested and sharp. Passed.",f:{h:-12},ft:"Busted the approach. Washed out."}]},{t:"Battalion Staff Hell",tier:"officer",i:"laptop",d:"You've been moved to battalion staff. Your job is now spreadsheets and meetings about meetings. How do you cope?",c:[{l:"Become an Excel wizard",w:{sm:6,perf:6},wt:"You automated half your job. The XO thinks you're a genius."},{l:"Request to go back to the line",p:.3,w:{h:8},wt:"Approved! Back with the troops.",f:{h:-5},ft:"Denied. Another meeting at 1600."}]},{t:"Ethics Gift",tier:"officer",i:"star",d:'A defense contractor offers you a "free" Super Bowl trip after you approve their vendor bid. What do you do?',c:[{l:"Decline and report it",w:{perf:6},wt:"Ethics counselor thanked you. Contractor got flagged."},{l:"Take the trip",p:.3,w:{h:15},wt:"Great seats. Nobody found out.",f:{court:"accepting illegal gratuities",discharge:"general",h:-20},ft:"IG investigation. Charged with accepting gratuities and forced out."}]},{t:"Platoon Firefight",tier:"officer",i:"gun",d:"Your platoon is pinned down by machine gun fire from a tree line in {country}. Your radio operator is waiting for orders. What do you do?",c:[{l:"Call for fire support",p:.75,w:{perf:12},wt:"Artillery silenced the gun. Nobody lost.",f:{wound:1},ft:"Danger close. Fragments hit you. Medevac."},{l:"Lead a flanking assault",p:.6,w:{perf:15,medal:"Bronze Star"},wt:"You flanked and took the position. Bronze Star with V.",f:{wound:1,die:.12,cause:"killed leading an assault"},ft:"A round hit you in the hip as you crossed open ground."},{l:"Break contact",w:{perf:-4},wt:"Everyone made it out. Mission incomplete."}]},{t:"Married to the Job",tier:"officer",i:"star",d:'You\'ve worked 80-hour weeks for months. Your spouse says, "I feel like a single parent." What do you do?',c:[{l:"Take leave",w:{h:10,perf:-3},wt:"A week at the beach. Your family remembered who you are."},{l:"Promise to do better later",w:{h:-8},wt:"Later never came. Couples counseling is next."}]},{t:"Air Assault School",tier:"officer",i:"helicopter",d:"You have a slot for air assault school. It's famous for brutal ruck marches and rappelling off helicopters. Go?",c:[{l:"Go for it",p:.65,w:{perf:8,he:4},wt:"You earned the wings. Your platoon respects you more.",f:{he:-8,h:-6},ft:"Failed the 12-mile ruck by two minutes."},{l:"Pass the slot to a sergeant",w:{rel:5,perf:3},wt:"He graduated. He'll remember your gesture."}]},{t:"Morale Event",tier:"officer",i:"star",d:"You're planning a company morale event. Budget: $0. Expectations: high. What do you do?",c:[{l:"Organize a chili cook-off",w:{perf:6,h:5},wt:"Fifteen chilis. One hospitalization. Great success."},{l:"Mandatory fun run",w:{perf:-2},wt:"Nothing says morale like running at 0530."}]},{t:"Relieved of Command?",tier:"officer",i:"eagle",d:"A soldier in your company was killed in a training accident. The investigation is examining your safety procedures. How do you handle it?",c:[{l:"Cooperate fully",p:.7,w:{perf:-3,h:-10},wt:"You were cleared. You still think about it every day.",f:{perf:-25,h:-15},ft:"Relieved for loss of confidence. Your career is likely over."},{l:"Lawyer up",w:{perf:-5,money:-3e3},wt:"Cleared. But people noticed you got defensive."}]},{t:"Port Visit Brief",tier:"officer",i:"trident",d:"You're liberty officer for a port visit to {country}. 400 sailors. You must keep them out of jail. Strategy?",c:[{l:"Strict buddy rule",w:{perf:6},wt:"Zero incidents. A miracle at sea."},{l:"Trust the crew",p:.4,w:{perf:4,h:3},wt:"Only two minor incidents.",f:{perf:-10},ft:"A sailor tried to steal a horse. International incident."}]},{t:"Captain's Career Course",tier:"officer",i:"map",d:"You're at the career course. Your study group wants to copy last year's answers. What do you do?",c:[{l:"Do your own work",w:{sm:5},wt:"You learned and graduated honestly."},{l:"Copy along",p:.6,w:{h:4},wt:"Easy A.",f:{court:"academic dishonesty",perf:-20},ft:"The instructor noticed. Honor code violation."}]},{t:"Battalion Budget",tier:"senior",i:"laptop",d:"It's September. Your battalion must spend $2 million in two weeks or lose it next year. What do you buy?",c:[{l:"New gym equipment",w:{perf:5,h:5},wt:"The soldiers love it. Morale up."},{l:"Office furniture",w:{perf:2},wt:"Ergonomic chairs for everyone. Thrilling."},{l:"Return the money",w:{perf:-6,sm:2},wt:"Fiscally honorable. The brigade commander thinks you're crazy."}]},{t:"Congressional Visit",tier:"senior",i:"flag",d:"A member of Congress is touring your installation tomorrow. The barracks have mold and broken AC. What do you show them?",c:[{l:"Show them the real barracks",p:.5,w:{perf:8},wt:"Funding approved for renovation within a year.",f:{perf:-10},ft:"The general is furious you embarrassed the command."},{l:"Polish the showcase building",w:{perf:4},wt:"Tour went well. Nothing changed."}]},{t:"Media Interview",tier:"senior",i:"radio",d:"A national reporter asks you about a recent training accident on camera. Public affairs is sweating. What do you say?",c:[{l:"Be candid and compassionate",p:.7,w:{perf:8},wt:"Clip went viral for the right reasons.",f:{perf:-6},ft:"One sentence was taken out of context."},{l:'"No comment"',w:{perf:-2},wt:'Headline: "Commander Dodges Questions."'}]},{t:"General's Pet Project",tier:"senior",i:"eagle",d:'The two-star wants your brigade to pilot a new "Wellness Initiative" with 47 mandatory briefings. Your soldiers are drowning in requirements. What do you do?',c:[{l:"Salute and execute",w:{perf:6,h:-4},wt:"The general is pleased. Your troops are not."},{l:"Push back with data",p:.5,w:{perf:8},wt:"The general trimmed it to 10 briefings. You're a hero.",f:{perf:-10},ft:'The general called you "not a team player." Ouch.'}]},{t:"Brigade Command Selection",tier:"senior",i:"medal",d:"The centralized selection list is out. Your name is on it as an alternate. What do you do?",c:[{l:"Wait patiently",p:.4,w:{promote:1,h:10},wt:"A principal declined. You're in command.",f:{h:-8},ft:"No slot opened. Next year."},{l:"Call your mentors",p:.5,w:{promote:1},wt:"Someone made a call. You're in.",f:{perf:-3},ft:"Looked desperate. Nothing changed."}]},{t:"Toxic Leader Complaint",tier:"senior",i:"policeman",d:"A command climate survey shows one of your battalion commanders is toxic. He's also your best tactician. What do you do?",c:[{l:"Relieve him",w:{perf:6,h:-4},wt:"Hard call. The battalion's climate improved fast."},{l:"Counsel him",p:.5,w:{perf:4},wt:"He changed his ways. Somewhat.",f:{perf:-8},ft:"A soldier's suicide note named him. Now it's on you."}]},{t:"Hurricane Relief",tier:"senior",i:"helicopter",d:"A major hurricane hit the coast. You've been put in charge of joint relief operations. Roads are flooded and communications are down. Priorities?",c:[{l:"Air rescue first",w:{perf:10,h:8},wt:"Your helicopters pulled 300 people off rooftops."},{l:"Restore communications",w:{perf:8},wt:"Once comms came up, everything got faster."},{l:"Wait for higher guidance",w:{perf:-8},wt:"Precious hours lost. Criticism in the news."}]},{t:"Retirement Decision",tier:"senior",i:"flag",d:"You have 26 years in. A defense contractor offers you triple your salary to retire and consult. What do you do?",c:[{l:"Retire and cash in",w:{money:15e4,h:8,discharge:"honorable"},wt:"Retired with honors. Now you sell drones to your old friends."},{l:"Stay in for stars",w:{perf:6},wt:"You're going for general. Family sighs."}]},{t:"Foreign Dignitary",tier:"senior",i:"flag",d:"A foreign general from {country} is visiting and serves you a local delicacy: fermented sheep eye. Everyone watches. What do you do?",c:[{l:"Eat it with a smile",w:{perf:8,he:-2},wt:"Diplomatic success. Your stomach disagrees."},{l:"Politely decline",w:{perf:-4},wt:"Awkward. The partnership stalled for a week."}]},{t:"Classified Briefing Leak",tier:"senior",i:"satellite",d:"Your staff's classified briefing just appeared on a gaming chat server. The press is calling. What's your move?",c:[{l:"Launch an investigation",w:{perf:4},wt:"It was a junior analyst trying to win an argument. Contained."},{l:"Downplay it",p:.3,w:{perf:2},wt:"It blew over.",f:{perf:-20},ft:"Congress demanded answers. Your career took a hit."}]},{t:"Pentagon Assignment",tier:"senior",i:"eagle",d:"You've been assigned to the Pentagon. Long hours, no troops, endless staff work. How do you approach it?",c:[{l:"Network hard",w:{perf:8,h:-4},wt:"You met all the right people. Stars may be in your future."},{l:"Count the days",w:{h:-6},wt:"You survived. Barely."}]},{t:"Suicide Stand-Down",tier:"senior",i:"stethoscope",d:"Your installation has lost four soldiers to suicide in two months. What do you do?",c:[{l:"Overhaul mental health access",w:{perf:10,h:-4},wt:"Embedded counselors, no-stigma policies. Numbers improved."},{l:"Mandatory briefing",w:{perf:-4},wt:"Another PowerPoint. Nothing changed."}]},{t:"General Officer Board",tier:"senior",i:"star",d:"Your file is in front of the general officer selection board. One black mark from a decade ago. What do you do?",c:[{l:"Hope your record speaks",p:.35,w:{promote:1,h:15},wt:"Selected for general. Stars!",f:{h:-10},ft:"Not selected. Your career may have peaked."},{l:"Write a letter to the board",p:.45,w:{promote:1,h:15},wt:"Your explanation landed. Selected.",f:{h:-8},ft:"It drew more attention to the issue."}]},{t:"IED on the Route",tier:"any",i:"bomb",d:"Your convoy is rolling through {country} when the lead vehicle stops. Something looks off in the road ahead. What do you do?",c:[{l:"Call EOD and wait",w:{perf:6},wt:"EOD found a pressure plate IED. Patience saved lives."},{l:"Drive around it",p:.5,w:{perf:2},wt:"You made it around.",f:{wound:1,he:-25,die:.1,cause:"killed by an IED"},ft:"A secondary device detonated under your vehicle."}]},{t:"Mortar Attack",tier:"any",i:"bomb",d:'The base sirens wail: "INCOMING!" You\'re in the shower, naked and soapy. What do you do?',c:[{l:"Sprint to the bunker",w:{h:2},wt:"You made it in a towel. Everyone has seen everything now."},{l:"Hit the deck where you are",p:.85,w:{h:-3},wt:"Rounds landed 200 meters away. Back to the shower.",f:{wound:1,he:-15},ft:"Shrapnel punched through the shower trailer."}]},{t:"Ambush",tier:"any",i:"gun",d:"Your patrol in {country} gets ambushed. Rounds are cracking overhead and {buddy} is down in the open. What do you do?",c:[{l:"Drag {buddy} to cover",p:.6,w:{rel:20,medal:"Bronze Star",perf:12},wt:"You pulled {buddy} behind a wall under fire. Bronze Star.",f:{wound:1,die:.12,cause:"killed rescuing a buddy under fire"},ft:"You were hit getting to {buddy}."},{l:"Return fire",p:.75,w:{perf:8},wt:"Your fire suppressed them. A medic got to {buddy}.",f:{wound:1},ft:"A round hit your arm."},{l:"Freeze",w:{h:-15,rel:-10},wt:"You couldn't move. Someone else saved {buddy}. You can't forgive yourself."}]},{t:"Grenade in the Room",tier:"any",i:"bomb",d:"A grenade bounces into the room where your squad is taking cover. There's no time. What do you do?",c:[{l:"Jump on it",p:.25,w:{medal:"Medal of Honor",perf:25,h:10,wound:1},wt:"Your body armor absorbed most of it. You survived. Medal of Honor.",f:{die:.9,cause:"killed smothering a grenade to save the squad"},ft:"You saved everyone in that room."},{l:"Kick it out",p:.5,w:{perf:10},wt:"It exploded outside. Everyone lived.",f:{wound:1,he:-30},ft:"It went off at the doorway."},{l:"Dive for cover",p:.6,w:{},wt:"Everyone dove. Minor injuries.",f:{wound:1},ft:"Fragments in your legs."}]},{t:"Sniper Fire",tier:"any",i:"bullseye",d:"A single shot cracks past your head on an observation post. A sniper is somewhere in the buildings. What do you do?",c:[{l:"Get down and report",w:{perf:4},wt:"Air support handled the building. You're shaken but alive."},{l:"Try to spot him",p:.5,w:{perf:10},wt:"You spotted the glint. Called it in. Threat eliminated.",f:{wound:1,die:.15,cause:"killed by a sniper"},ft:"He saw you first."}]},{t:"Medevac Call",tier:"any",i:"helicopter",d:"A soldier is bleeding out on a dusty field. The medevac is 30 minutes away. You're the closest one with a tourniquet. What do you do?",c:[{l:"Apply the tourniquet",p:.8,w:{perf:10,h:6},wt:"You stopped the bleed. He made it to surgery.",f:{h:-15},ft:"You did everything right. He didn't make it."},{l:"Wait for the medic",w:{h:-10},wt:"The medic got there. It was close."}]},{t:"PTSD Nightmare",tier:"any",i:"skull",d:"Since returning from {country}, you wake up drenched in sweat, hearing explosions. Fireworks make you hit the ground. What do you do?",c:[{l:"Go to behavioral health",w:{h:10,he:4},wt:"Therapy is hard but helping."},{l:"Drink to sleep",w:{h:-6,he:-8},wt:"It works until it doesn't."},{l:"Talk to {buddy}",w:{h:6,rel:8},wt:"{buddy} has the same dreams. You're not alone."}]},{t:"VA Claim",tier:"any",i:"stethoscope",d:"Your back, knees, and hearing are shot. The VA claim process is 80 pages long. What do you do?",c:[{l:"Get a VSO to help",w:{money:2e3,h:6},wt:"A Veterans Service Officer got you a fair rating."},{l:"Do it yourself",p:.5,w:{money:1500,sm:2},wt:"Approved. You're a bureaucratic warrior.",f:{h:-8},ft:"Denied. Appeal pending. Forever."},{l:"Don't bother",w:{he:-3},wt:'"Other people need it more." Your knees disagree.'}]},{t:"Homecoming",tier:"any",i:"flag",d:"After nine months in {country}, your plane lands. Your family is in the gym waiting with signs. How do you feel?",c:[{l:"Run to them",w:{h:20},wt:"Hugs, tears, and your dog lost its mind."},{l:"Hang back, overwhelmed",w:{h:5},wt:"It's a lot. Readjusting will take time."}]},{t:"PCS Move",tier:"any",i:"map",d:"You got orders to a new duty station across the country. The movers broke your TV and lost a box. What do you do?",c:[{l:"File a claim",p:.6,w:{money:800},wt:"Reimbursed in only four months!",f:{h:-5},ft:'Claim denied. "Pre-existing damage."'},{l:"Do a DITY move next time",w:{money:1500,he:-4},wt:"You moved yourself and pocketed the difference."}]},{t:"Spouse Strain",tier:"any",i:"star",d:"Between deployments and field time, you've been home 90 days this year. Your spouse says they're exhausted. What do you do?",c:[{l:"Marriage retreat",w:{h:10},wt:"The chaplain-run retreat helped more than you expected."},{l:"Ignore it",w:{h:-12},wt:"They moved back to their parents' place."},{l:"Talk honestly",p:.6,w:{h:8},wt:"A long, hard conversation. You're okay.",f:{h:-8},ft:"It turned into a fight."}]},{t:"Earthquake Relief",tier:"any",i:"helicopter",d:"Your unit is deployed to help after a massive earthquake in {country}. A child is trapped under rubble. What do you do?",c:[{l:"Dig with your hands",p:.7,w:{h:15,perf:8},wt:"You pulled her out alive. Her mother kissed your hands.",f:{he:-10,h:-10},ft:"An aftershock collapsed more rubble. You were too late."},{l:"Wait for heavy equipment",w:{h:-4},wt:"The crane arrived. She survived, barely."}]},{t:"GI Bill",tier:"any",i:"star",d:"You're eligible for the GI Bill. College, trade school, or transfer it to your kid?",c:[{l:"Go to college",w:{sm:10,money:1500},wt:"Tuition paid plus a housing stipend."},{l:"Trade school",w:{sm:5,money:2e3},wt:"Welding certification. Solid."},{l:"Transfer to your child",w:{h:6},wt:"Your kid will go to college debt-free."}]},{t:"Mail From Home",tier:"any",i:"radio",d:"You get a care package from an elementary school class. Crayon drawings and beef jerky. What do you do?",c:[{l:"Write them back",w:{h:8},wt:"They framed your letter in the classroom."},{l:"Share the jerky",w:{h:5,rel:5},wt:"Your squad loved it."}]},{t:"Hearing Loss",tier:"any",i:"stethoscope",d:"Your ears have been ringing for a week after a live-fire exercise without proper protection. What do you do?",c:[{l:"Get it checked",w:{he:2},wt:"Mild damage documented. Good for future VA claims."},{l:"Ignore it",w:{he:-5},wt:'"What?" You say that a lot now.'}]},{t:"Rocket Attack",tier:"any",i:"bomb",d:"Rockets are hitting the base in {country}. You're crossing open ground near the motor pool. What do you do?",c:[{l:"Dive into a ditch",p:.85,w:{h:-4},wt:"Dirt in your teeth, but alive.",f:{wound:1,he:-15},ft:"Shrapnel caught your shoulder."},{l:"Run for the bunker",p:.7,w:{h:-2},wt:"Made it in time.",f:{wound:1,die:.08,cause:"killed in a rocket attack"},ft:"A rocket landed close."}]},{t:"Buddy Killed",tier:"any",i:"skull",d:"{buddy} was killed by a roadside bomb this morning. The memorial is tomorrow. How do you deal with it?",c:[{l:"Speak at the memorial",w:{h:-10,rel:10},wt:"You told the funny stories. Everyone laughed and cried."},{l:"Bottle it up",w:{h:-20,he:-5},wt:"You haven't cried. You haven't slept either."},{l:"Visit the chaplain",w:{h:-6},wt:"It didn't fix anything. But it helped."}]},{t:"Animal Mascot",tier:"any",i:"helmet",d:"A stray cat has adopted your outpost in {country}. General Order No. 1 prohibits pets. Keep it?",c:[{l:"Keep it hidden",p:.6,w:{h:12},wt:"Sergeant Whiskers keeps the rats away. Morale soars.",f:{perf:-4,h:-6},ft:"The command sergeant major found Whiskers."},{l:"Ship it home",w:{h:10,money:-2e3},wt:"Through a nonprofit, Whiskers now lives with your family."}]},{t:"Burn Pit",tier:"any",i:"fire",d:"You've been assigned to burn pit duty. The black smoke smells like plastic and death. No respirator available. What do you do?",c:[{l:"Do the job",w:{he:-10,perf:3},wt:"You coughed for a month. Hope it doesn't catch up later."},{l:"Complain to medical",p:.5,w:{he:-3},wt:"They found you a mask.",f:{he:-8},ft:'"No masks in stock."'}]},{t:"Coast Guard Drug Bust",tier:"any",i:"trident",d:"Your cutter intercepts a semi-submersible full of cocaine. The smugglers are scrambling to scuttle it. What do you do?",c:[{l:"Board immediately",p:.7,w:{perf:12,h:8},wt:"4,000 pounds seized. Headlines back home.",f:{he:-10},ft:"It sank fast. You barely got off it."},{l:"Rescue the crew first",w:{perf:6},wt:"Crew detained. Most of the drugs sank, but nobody died."}]},{t:"Satellite Downlink",tier:"any",i:"satellite",d:"You're monitoring satellite feeds and see a convoy forming near friendly troops. It might be civilians. What do you report?",c:[{l:"Report what you see, no guess",w:{perf:6},wt:"Command got more eyes on it. Civilians. A bad call avoided."},{l:"Flag it as hostile",w:{perf:-8,h:-10},wt:"It was a wedding party. You think about it constantly."}]},{t:"Base Housing Lottery",tier:"any",i:"map",d:'Base housing has a waiting list of six months. A friend says he knows "a guy" who can bump you up for $500. What do you do?',c:[{l:"Pay the guy",p:.4,w:{money:-500,h:8},wt:"Keys in a week.",f:{money:-500,njp:1},ft:"The guy was a scammer. And you're now in an investigation."},{l:"Wait your turn",w:{h:-3},wt:"Six months in a budget hotel. You hate it."}]},{t:"Typhoon at Sea",tier:"any",i:"trident",d:"A typhoon is battering the ship. Waves are crashing over the bow and something is loose on deck. What do you do?",c:[{l:"Secure it",p:.6,w:{perf:8},wt:"Tethered and secured. Chief nodded at you.",f:{he:-20,die:.05,cause:"swept overboard in a typhoon"},ft:"A wave slammed you into a bulkhead."},{l:"Stay inside",w:{perf:-3},wt:"It broke loose and smashed a radar mast."}]},{t:"Interpreter's Plea",tier:"any",i:"radio",d:"The interpreter who saved your life in {country} is now being hunted. He emails you for a visa recommendation. What do you do?",c:[{l:"Write the letter",w:{h:10},wt:"He got a visa. You picked him up from the airport."},{l:"Ignore the email",w:{h:-15},wt:"You never heard from him again."}]},{t:"Drunk Brawl Overseas",tier:"any",i:"policeman",d:"In a bar in {country}, a local starts a fight with {buddy}. The local police are already nearby. What do you do?",c:[{l:"Pull {buddy} out",w:{rel:8},wt:"You dragged {buddy} out the back door. International incident avoided."},{l:"Join the fight",p:.3,w:{rel:10,h:5},wt:"You won and fled. Legends.",f:{court:"assault overseas",h:-20},ft:"Arrested. The embassy got involved."}]},{t:"Wrong Way Bombing Range",tier:"any",i:"jet",d:"During a live-fire exercise, you notice a vehicle has wandered onto the bombing range. Jets are inbound. What do you do?",c:[{l:'Call "Knock it off!"',w:{perf:12},wt:"Strike aborted. A lost farmer. You saved his life."},{l:"Assume someone else sees it",p:.5,w:{},wt:"Someone else called it.",f:{h:-30,perf:-15},ft:"Tragedy. You will relive it forever."}]},{t:"Medical Board",tier:"any",i:"stethoscope",d:"Your back injury is getting worse. The doctor recommends a medical board, which could end your career. What do you do?",c:[{l:"Accept the board",w:{discharge:"honorable",money:5e3},wt:"Medically retired. A new chapter."},{l:"Hide the pain",w:{he:-10,perf:3},wt:"You're still in. But at what cost?"}]},{t:"Wildfire Support",tier:"any",i:"fire",d:"A massive wildfire is threatening a town near base. The governor requests military help. You volunteer. What do you do?",c:[{l:"Dig firebreaks",w:{he:-4,perf:6,h:6},wt:"Exhausting work. The town was saved."},{l:"Help evacuate residents",w:{perf:6,h:8},wt:"You carried an elderly man to safety. He cried."}]},{t:"Chow Hall Mystery Meat",tier:"any",i:"tent",d:'The dining facility is serving something labeled "Meat." Just "Meat." You\'re starving. Eat it?',c:[{l:"Eat it",p:.6,w:{h:2},wt:"Surprisingly decent. You still don't know what it was.",f:{he:-8},ft:"Food poisoning. Two days on the toilet."},{l:"Go for the salad bar",w:{he:2},wt:"Iceberg lettuce and ranch. Living the dream."}]},{t:"Ghost Story",tier:"any",i:"skull",d:"Night watch in an old building on base. You hear footsteps on the floor above. It's supposed to be empty. What do you do?",c:[{l:"Investigate",p:.7,w:{h:4},wt:"It was a raccoon. You screamed louder than it did.",f:{h:-5},ft:"Nothing there. But the door you locked is now open."},{l:"Turn up the radio",w:{h:-2},wt:"You didn't sleep for days."}]},{t:"Hidden Camera",tier:"any",i:"laptop",d:"You find out someone has been recording people in the shower trailers. You know who it is. What do you do?",c:[{l:"Report to CID",w:{perf:8},wt:"He was arrested and court-martialed."},{l:"Confront him",p:.5,w:{perf:4},wt:"He broke down and confessed.",f:{he:-6},ft:"He attacked you and destroyed the evidence."}]},{t:"Veterans Day",tier:"any",i:"flag",d:"A stranger at a restaurant thanks you for your service and wants to pay for your meal. What do you do?",c:[{l:"Accept graciously",w:{h:6,money:30},wt:"Nice gesture. You tipped the waitress extra."},{l:"Politely decline",w:{h:3},wt:"Awkward smiles all around."}]},{t:"Election Politics",tier:"any",i:"flag",d:"A fellow service member is posting heated political rants in uniform on social media. What do you do?",c:[{l:"Remind them of the rules",w:{perf:3,rel:-2},wt:"They deleted it. Barely."},{l:"Join the argument",w:{perf:-8,h:2},wt:"Now you're both in trouble."}]},{t:"Comms Down",tier:"any",i:"radio",d:"Your unit lost radio contact with higher in {country}. You're the only one who knows the backup satellite system. What do you do?",c:[{l:"Set it up under pressure",p:.7,w:{perf:10,sm:3},wt:"Comms restored in four minutes. They called you a wizard.",f:{perf:-5},ft:"The battery was dead. Nobody charged it."},{l:"Send a runner",w:{perf:3},wt:"Old school, but it worked."}]},{t:"Uniform Shopping",tier:"any",i:"helmet",d:"You need new boots. The issue ones gave you blisters. The PX sells $250 boots that are actually comfortable. Buy?",c:[{l:"Buy the good boots",w:{money:-250,he:4},wt:"Your feet thank you every single day."},{l:"Tough it out",w:{he:-4},wt:"Blisters forever."}]},{t:"Hometown Hero",tier:"any",i:"medal",d:"Your hometown newspaper wants to do a story about your service. Your old high school bully reads it. What do you say in the interview?",c:[{l:"Stay humble",w:{h:6},wt:"Classy article. Your mom framed it."},{l:"Exaggerate a bit",w:{h:8,perf:-2},wt:"You might have implied you were a Navy SEAL. You were not."}]}];